    for u in range(v):
        edge_vars.append(edge_idx(u, v) + 1)
    for w in range(v+1, n):
        edge_vars.append(edge_idx(v, w) + 1)

    if len(edge_vars) > 6:
        for subset in combinations(edge_vars, 7):
            clauses.append([-x for x in subset])

    if len(edge_vars) > 3:
        for subset in combinations(edge_vars, len(edge_vars) - 2):
            clauses.append(list(subset))

# No triangles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            e1 = edge_idx(i, j) + 1
            e2 = edge_idx(i, k) + 1
            e3 = edge_idx(j, k) + 1
            clauses.append([-e1, -e2, -e3])

# No 4-cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                e1 = edge_idx(i, j) + 1
                e2 = edge_idx(j, k) + 1
                e3 = edge_idx(k, l) + 1
                e4 = edge_idx(i, l) + 1
                clauses.append([-e1, -e2, -e3, -e4])

                e2b = edge_idx(j, l) + 1
                e3b = edge_idx(k, l) + 1
                e4b = edge_idx(i, k) + 1
                clauses.append([-e1, -e2b, -e3b, -e4b])

                e1c = edge_idx(i, k) + 1
                e2c = edge_idx(j, k) + 1
                e3c = edge_idx(j, l) + 1
                e4c = edge_idx(i, l) + 1
                clauses.append([-e1c, -e2c, -e3c, -e4c])

print(f"Base clauses: {len(clauses)}")

def find_cycles_of_length_k(adj, n, k):
    """Find all cycles of exact length k"""
    cycles = set()
    for start in range(n):
        # DFS with path tracking
        stack = [(start, [start])]
        while stack:
            node, path = stack.pop()
            if len(path) == k:
                if start in adj[node]:
                    # Found a cycle
                    # Normalize: rotate so smallest vertex is first
                    min_idx = path.index(min(path))
                    normalized = tuple(path[min_idx:] + path[:min_idx])
                    # Also consider reverse
                    rev = tuple([normalized[0]] + list(reversed(normalized[1:])))
                    cycle_key = min(normalized, rev)
                    cycles.add(cycle_key)
                continue
            for neighbor in adj[node]:
                if neighbor not in path and len(path) < k:
                    stack.append((neighbor, path + [neighbor]))
    return cycles

def get_cycle_edges(cycle):
    """Get edge variables for a cycle"""
    k = len(cycle)
    edge_vars = []
    for i in range(k):
        u, v = cycle[i], cycle[(i+1) % k]
        if u > v:
            u, v = v, u
        edge_vars.append(edge_idx(u, v) + 1)
    return edge_vars

# Incremental solving
for iteration in range(30):
    print(f"\nIteration {iteration}")
    solver = Glucose3()
    for clause in clauses:
        solver.add_clause(clause)

    if solver.solve():
        model = solver.get_model()
        edges = []
        for i in range(n):
            for j in range(i+1, n):
                idx = edge_idx(i, j) + 1
                if model[idx - 1] > 0:
                    edges.append((i, j))

        adj = [set() for _ in range(n)]
        for u, v in edges:
            adj[u].add(v)
            adj[v].add(u)

        degrees = [len(adj[v]) for v in range(n)]
        print(f"  Edges: {len(edges)}, Degrees: min={min(degrees)}, max={max(degrees)}")

        # Check for short cycles
        found_short = False
        for length in range(3, 7):
            cycles = find_cycles_of_length_k(adj, n, length)
            if cycles:
                print(f"  Found {len(cycles)} cycles of length {length}")
                found_short = True
                # Add constraints to break these cycles
                for cycle in cycles:
                    cycle_edge_vars = get_cycle_edges(cycle)
                    clauses.append([-x for x in cycle_edge_vars])

        if not found_short:
            print("  SUCCESS! No short cycles found!")
            print(f"  Edge list: {sorted(edges)}")
            solver.delete()
            break

        solver.delete()
    else:
        print("  UNSAT")
        solver.delete()
        break
